DOCUMENTS = [{'id': 0, 'category': 'معابد', 'text': 'معبد فيلة يقع على جزيرة أجيليكيا بعد نقله من موقعه الأصلي إنقاذاً له من مياه بحيرة ناصر، وهو مخصص لعبادة الإلهة إيزيس ويعد من أجمل المعابد المصرية على الإطلاق.'}, {'id': 1, 'category': 'معابد', 'text': 'يقام في معبد فيلة عرض للصوت والضوء في المساء يحكي أسطورة إيزيس وأوزوريس، ويجذب هذا العرض آلاف الزوار سنوياً للاستمتاع بالإضاءة الملونة على أعمدة المعبد.'}, {'id': 2, 'category': 'معابد', 'text': 'معبدا أبو سمبل الكبير والصغير نحتهما رمسيس الثاني في الصخر تخليداً لانتصاراته وتكريماً لزوجته الملكة نفرتاري، ويقعان جنوب أسوان على بحيرة ناصر.'}, {'id': 3, 'category': 'معابد', 'text': 'تحدث ظاهرة تعامد الشمس على وجه رمسيس الثاني داخل معبد أبو سمبل مرتين كل عام، في الثاني والعشرين من فبراير والثاني والعشرين من أكتوبر، ويحضرها آلاف الزوار من أنحاء العالم.'}, {'id': 4, 'category': 'معابد', 'text': 'معبد كلابشة يعد من أكبر المعابد النوبية التي تم نقلها وإعادة بنائها بالقرب من السد العالي، وهو مخصص لعبادة الإله ماندوليس رب الشمس عند النوبيين.'}, {'id': 5, 'category': 'معابد', 'text': 'معبد بيت الوالي يقع بجوار معبد كلابشة وهو منحوت في الصخر، ونقشت جدرانه بمشاهد حربية تصور انتصارات رمسيس الثاني على النوبيين والليبيين.'}, {'id': 6, 'category': 'معالم أثرية', 'text': 'المسلة الناقصة تقع في المحاجر الشمالية بأسوان، وهي أكبر مسلة معروفة في مصر القديمة، تُظهر شقوقاً في الجرانيت أوقفت استكمال نحتها وفصلها عن الصخر.'}, {'id': 7, 'category': 'معالم أثرية', 'text': 'توضح المسلة الناقصة للزوار طريقة قدماء المصريين في استخراج المسلات من محاجر الجرانيت، وتعتبر شاهداً مهماً على تقنيات النحت والنقل في العصر الفرعوني.'}, {'id': 8, 'category': 'معالم أثرية', 'text': 'جزيرة الفنتين تقع وسط النيل أمام مدينة أسوان مباشرة، وتضم آثار معبد خنوم وقرى نوبية ملونة ومتحف أسوان الذي يعرض قطعاً من مختلف العصور.'}, {'id': 9, 'category': 'سدود', 'text': 'السد العالي بأسوان أحد أهم المشروعات الهندسية في القرن العشرين، شُيّد لحماية مصر من الفيضانات وتوليد الكهرباء وتخزين المياه في بحيرة ناصر.'}, {'id': 10, 'category': 'سدود', 'text': 'خزان أسوان القديم الذي بُني في بدايات القرن العشرين يقع جنوب مدينة أسوان مباشرة، ويعد من أوائل السدود الكبرى التي أقيمت على نهر النيل.'}, {'id': 11, 'category': 'حدائق ومتنزهات', 'text': 'جزيرة كتشنر، المعروفة أيضاً بالحديقة النباتية، تضم مئات الأنواع النادرة من النباتات والأشجار الاستوائية التي جمعها اللورد كتشنر من مختلف أنحاء العالم.'}, {'id': 12, 'category': 'حدائق ومتنزهات', 'text': 'يفضل الزوار التجول في الحديقة النباتية بجزيرة كتشنر عصراً حيث يمكن مشاهدة الطيور النادرة والاستمتاع بمناظر النيل الهادئة بين أشجار النخيل والمانجو.'}, {'id': 13, 'category': 'حدائق ومتنزهات', 'text': 'كورنيش أسوان يمتد على طول ضفة النيل الشرقية، وهو مكان مفضل للمشي والفسحة العائلية مساءً، ويضم مقاهي ومطاعم مطلة مباشرة على النهر.'}, {'id': 14, 'category': 'نزهات نيلية', 'text': 'رحلات الفلوكة في أسوان من أشهر أنشطة الترفيه، حيث يستقل السياح والزوار المحليون قوارب شراعية تقليدية للتجول بين الجزر الصخرية عند الغروب.'}, {'id': 15, 'category': 'نزهات نيلية', 'text': 'يمكن للزائر استئجار فلوكة من الكورنيش للإبحار حول جزيرة النباتات وجزيرة الفنتين، وتعد رحلة المساء وقت الغروب من أجمل التجارب في أسوان.'}, {'id': 16, 'category': 'متاحف', 'text': 'المتحف النوبي يعرض تاريخ وحضارة النوبة عبر العصور من خلال قطع أثرية ومجسمات وأزياء تقليدية، وقد أُنشئ ضمن مشروع إنقاذ آثار النوبة الدولي.'}, {'id': 17, 'category': 'متاحف', 'text': 'متحف أسوان يقع في مبنى قديم على جزيرة الفنتين ويعرض مقتنيات اكتُشفت في المنطقة، من تماثيل وأواني فخارية تعود لعصور فرعونية ورومانية مختلفة.'}, {'id': 18, 'category': 'ثقافة وعادات', 'text': 'يتميز النوبيون بألوانهم الزاهية في تزيين منازلهم، حيث تُطلى الجدران بألوان مبهجة وتُرسم عليها زخارف تمثل النخيل والتماسيح رمزاً للحماية والخصوبة.'}, {'id': 19, 'category': 'ثقافة وعادات', 'text': 'من عادات النوبيين الترحيب بالضيوف بتقديم القهوة أو الشاي فور الوصول، وتعد الضيافة جزءاً أساسياً من الهوية النوبية المعروفة بكرمها.'}, {'id': 20, 'category': 'ثقافة وعادات', 'text': 'يحتفظ سكان النوبة بلغتهم الخاصة وأغانيهم الشعبية المصحوبة بآلة الطار والدف، وتُنقل هذه التقاليد الشفهية من جيل إلى جيل حتى اليوم.'}, {'id': 21, 'category': 'ثقافة وعادات', 'text': 'السبوع هو احتفال تقليدي يقام في اليوم السابع لميلاد الطفل في أسوان والنوبة، حيث يجتمع الأهل والجيران وتُغنى أغاني خاصة بهذه المناسبة.'}, {'id': 22, 'category': 'ثقافة وعادات', 'text': 'تشتهر حفلات الزفاف النوبية بطقوس تمتد لعدة أيام، منها ليلة الحناء التي تُزيَّن فيها العروس بنقوش تقليدية وسط غناء ورقص جماعي.'}, {'id': 23, 'category': 'حرف يدوية', 'text': 'الحرف اليدوية النوبية مثل نسج السلال الملونة من سعف النخيل وصناعة الخرز والتطريز اليدوي تشكل مصدر دخل مهم للنساء في القرى النوبية.'}, {'id': 24, 'category': 'قرى وأسواق', 'text': 'القرى النوبية القريبة من أسوان مثل قرية غرب سهيل تجذب الزوار لمشاهدة البيوت الملونة والتفاعل مع التماسيح الأليفة التي يربيها بعض السكان.'}, {'id': 25, 'category': 'قرى وأسواق', 'text': 'سوق أسوان الشعبي يمتد بمحاذاة الكورنيش ويعرض التوابل الملونة والبخور والمنتجات النوبية اليدوية، ويعد وجهة مفضلة للتسوق والتجول مساءً.'}, {'id': 26, 'category': 'مطبخ محلي', 'text': 'الكركديه هو المشروب الأشهر في أسوان، يُصنع من نبات الكركديه المزروع محلياً، ويُقدَّم بارداً أو ساخناً وله شهرة تتجاوز حدود مصر.'}, {'id': 27, 'category': 'مطبخ محلي', 'text': 'يعتمد المطبخ النوبي على أطباق مثل الويكة والفتة النوبية والتمر واللحوم المطهوة ببطء، وتتميز الوجبات بنكهات مميزة موروثة عن أجداد النوبة.'}, {'id': 28, 'category': 'طبيعة', 'text': 'الجندل الأول هو منطقة الصخور الجرانيتية التي تعيق الملاحة جنوب أسوان، وتشكل مناظرها الطبيعية الفريدة مصدر جذب للزوار الباحثين عن هدوء النيل.'}, {'id': 29, 'category': 'طبيعة', 'text': 'تشتهر أسوان بمناخها الجاف الدافئ طوال العام تقريباً، مما يجعلها وجهة مثالية للسياحة الشتوية والاستشفاء من أمراض الروماتيزم والجهاز التنفسي.'}, {'id': 30, 'category': 'مهرجانات', 'text': 'مهرجان تعامد الشمس على معبد أبو سمبل يتحول إلى احتفال شعبي وفني كبير يضم عروضاً فلكلورية نوبية وفعاليات موسيقية تستمر طوال اليوم.'}, {'id': 31, 'category': 'أنشطة سياحية', 'text': 'تعد رحلة ركوب الجمال في الصحراء المحيطة بأسوان ومشاهدة غروب الشمس من أعلى التلال الرملية من الأنشطة المفضلة لدى السياح الباحثين عن مغامرة.'}, {'id': 32, 'category': 'أنشطة سياحية', 'text': 'بحيرة ناصر تتيح رحلات بحرية فاخرة لعدة أيام تمر بالمعابد النوبية المنقولة مثل أبو سمبل وكلابشة وعمدا، وتمنح تجربة مختلفة عن النيل التقليدي.'}, {'id': 33, 'category': 'مواصلات وموقع', 'text': 'تقع مدينة أسوان في أقصى جنوب مصر على الضفة الشرقية لنهر النيل، وتبعد عن القاهرة نحو تسعمائة كيلومتر ويمكن الوصول إليها بالطائرة أو القطار.'}, {'id': 34, 'category': 'عمارة نوبية', 'text': 'يُبنى البيت النوبي التقليدي من الطين اللبن على حافة الصحراء بين الجبل ونهر النيل، ويتكون غالباً من حوش مستطيل تحيط به الغرف، ومدخله الرئيسي يواجه النيل مباشرة.'}, {'id': 35, 'category': 'عمارة نوبية', 'text': 'تخلو أغلب البيوت النوبية من النوافذ الكبيرة، وتكتفي بفتحات علوية صغيرة تسمى الطاقات لتفادي برودة رياح الشتاء والحفاظ على برودة المنزل في فصل الصيف.'}, {'id': 36, 'category': 'زخارف ورموز', 'text': 'يزين النوبيون واجهات منازلهم برسوم هندسية ونباتية وحيوانية ملونة، ويُعتقد أن الغرض الأساسي منها هو درء الحسد وحماية أهل البيت من العين الحاسدة.'}, {'id': 37, 'category': 'زخارف ورموز', 'text': 'من أشهر الزخارف النوبية المثلث الذي يرمز للحماية من الحسد والسحر، والدائرة التي ترمز للشمس والقمر، والهلال الذي يوحي بالتفاؤل، والسمكة رمزاً للبعث وتجدد الحياة.'}, {'id': 38, 'category': 'حرف يدوية', 'text': 'تبرع النساء النوبيات في نسج أطباق وسلال من خوص النخيل ومراوح من الجريد، وتُعلَّق هذه المشغولات اليدوية على حوائط وأسقف المنزل لأغراض الزينة والحماية معاً.'}, {'id': 39, 'category': 'أزياء تقليدية', 'text': 'ترتدي المرأة النوبية جلباباً أسود واسع الأكمام يسمى التوب فوق جلباب آخر ملون، مع غطاء رأس يسمى الشبارة وخلخال في القدمين وحلية جلدية ملونة تتدلى على الصدر.'}, {'id': 40, 'category': 'أزياء تقليدية', 'text': 'يرتدي العريس النوبي يوم زفافه جلباباً أبيض وعمامة بيضاء ويحمل سيفاً وخنجراً رمزاً للشجاعة والرجولة، وينتعل حذاءً تقليدياً يسمى المركوب.'}, {'id': 41, 'category': 'طقوس الزواج', 'text': 'تبدأ مراسم الزواج النوبي بيوم يسمى بيرار نهار، حين تزور عائلة العريس بيت العروس حاملة الهدايا، ويُتفق خلاله على تفاصيل الزواج ومهر العروس وتُقرأ الفاتحة.'}, {'id': 42, 'category': 'طقوس الزواج', 'text': 'في مراسم تسمى أوكجر تطوف نساء عائلة العريس على بيوت القرية لإبلاغ الجيران بموعد الزفاف، حاملات طبقاً مزيناً بالزهور والعطور يسمى الكريدة.'}, {'id': 43, 'category': 'طقوس الزواج', 'text': 'ليلة الحناء عند النوبيين تسمى كوفري تور وتُعد من أقدس ليالي الزفاف، حيث تُزين العروس بالحناء وسط الغناء الفولكلوري والرقص الجماعي قبل ليلة الزفاف بيوم أو يومين.'}, {'id': 44, 'category': 'طقوس الزواج', 'text': 'من عادات الزواج النوبي أن يتحمل العريس الجزء الأكبر من تكاليف التجهيزات دون اشتراط قائمة عفش على العروس، وتندر حالات الطلاق في المجتمعات النوبية مقارنة بغيرها.'}, {'id': 45, 'category': 'طقوس الزواج', 'text': 'يفضّل المجتمع النوبي زواج الأقارب خصوصاً بين أبناء العمومة حفاظاً على تماسك العائلة والهوية النوبية، وهو ما يُعرف بنمط الزواج الداخلي.'}, {'id': 46, 'category': 'عادات المولود', 'text': 'بعد الولادة تمكث الأم فترة في بيت أهلها لترعاها والدتها، وتحرص العائلة على تقديم أطعمة مقوية خلال فترة النفاس وتجنّب خروج الأم من المنزل إلا للضرورة القصوى.'}, {'id': 47, 'category': 'طقوس الوفاة', 'text': 'عند وفاة أحد أفراد القرية النوبية يشارك جميع السكان في مراسم العزاء والدفن، ولا تحضر النساء عادة موكب تشييع الجنازة بل ينتظرن في المنزل لاستقبال المعزين.'}, {'id': 48, 'category': 'خلفية تاريخية', 'text': 'يُعتقد أن اسم النوبة مشتق من الكلمة المصرية القديمة نب وتعني الذهب، نسبة إلى مناجم الذهب التي اشتهرت بها المنطقة منذ العصور الفرعونية القديمة.'}, {'id': 49, 'category': 'خلفية تاريخية', 'text': 'ينقسم سكان النوبة المصرية تقليدياً إلى ثلاث مجموعات رئيسية هي الكنوز والفديجا والعرب، ولكل مجموعة لهجتها وبعض عاداتها الخاصة رغم تجاورها الجغرافي على امتداد النيل.'}, {'id': 50, 'category': 'طب شعبي', 'text': 'اعتمد أهل النوبة تاريخياً على طب شعبي مستمد من الأعشاب والنباتات البرية المحلية لعلاج بعض الأعراض البسيطة، إلى جانب استفادتهم من الخدمات الصحية الحديثة المتوفرة حالياً.'}]


